145	  [Methods.GetAllConsiliumSessions]: async (_, ctx) => {
146	    if (!ctx.workspaceRoot) return [];
147	
148	    // The SDK hashes workDir case-sensitively. On Windows the same folder can
149	    // appear under c:\ and C:\ hashes. Query every registered variant.
150	    const registered = getRegisteredWorkDirs(ctx.workspaceRoot);
151	    const allSessions: SessionInfo[] = [];
152	    const seen = new Set<string>();
153	
154	    // Scan Do sessions FIRST so they take priority over SDK regular sessions
155	    // that share the same UUID (Do sessions stored in ~/.consilium/do_sessions/
156	    // also appear as regular SDK sessions in ~/.consilium/sessions/{hash}/).
157	    const doSessions = await listDoSessions(registered);
158	    for (const ds of doSessions) {
159	      if (!seen.has(ds.id)) {
160	        seen.add(ds.id);
161	        const meta = ctx.getSessionMetadata(ds.id);
162	        ds.brief = meta?.title || ds.brief;
163	        (ds as any).mode = meta?.mode || 'do';
164	        allSessions.push(ds);
165	      }
166	    }
167	
168	    // Also scan workspace-local Think dirs
169	    for (const wd of registered) {
170	      const thinkDir = getWorkspaceThinkDir(wd);
171	      if (!fs.existsSync(thinkDir)) continue;
172	      const entries = await fs.promises.readdir(thinkDir, { withFileTypes: true });
173	      for (const e of entries) {
174	        if (!e.isDirectory() && e.name.endsWith(".jsonl")) {
175	          const id = e.name.slice(0, -".jsonl".length);
176	          if (!UUID_REGEX.test(id) || seen.has(id)) continue;
177	          seen.add(id);
178	          const filePath = path.join(thinkDir, e.name);
179	          const st = await fs.promises.stat(filePath);
180	          const brief = (await getFirstUserMessageFromThinkFile(filePath)) || DEFAULT_FALLBACK_TITLE;
181	          allSessions.push({
182	            id,
183	            workDir: '[Think]',
184	            updatedAt: st.mtimeMs || st.mtime.getTime(),
185	            contextFile: filePath,
186	            brief,
187	            isThinking: true,
188	          });
189	        }
190	      }
191	    }
192	
193	    // Then SDK regular sessions (remaining UUIDs not already claimed)
194	    for (const dir of registered) {
195	      try {
196	        const sess = await listSessions(dir);
197	        for (const s of sess) {
198	          if (!seen.has(s.id)) {
199	            seen.add(s.id);
200	            const meta = ctx.getSessionMetadata(s.id);
201	            s.brief = meta?.title || s.brief;
202	            (s as any).mode = meta?.mode || 'legacy';
203	            allSessions.push(s);
204	          }
205	        }
206	      } catch {
207	        // ignore missing directories
208	      }
209	    }
210	
211	    return allSessions.sort((a, b) => b.updatedAt - a.updatedAt);
212	  },
