230	  [Methods.BrowseWorkDir]: async (_, ctx) => {
231	    if (!ctx.workspaceRoot) {
232	      return { ok: false, workDir: null };
233	    }
234	    const workspaceUri = vscode.Uri.file(ctx.workspaceRoot);
235	    let subdirs: string[] = [];
236	    try {
237	      const entries = await vscode.workspace.fs.readDirectory(workspaceUri);
238	      subdirs = entries
239	        .filter(([, type]) => type === vscode.FileType.Directory)
240	        .map(([name]) => name)
241	        .filter((name) => !name.startsWith("."))
242	        .sort();
243	    } catch {
244	      // Ignore errors
245	    }
246	
247	    const items: vscode.QuickPickItem[] = [
248	      { label: "$(folder) Browse...", description: "Open folder picker", alwaysShow: true },
249	      { label: "", kind: vscode.QuickPickItemKind.Separator },
250	      ...subdirs.map((name) => ({
251	        label: `$(folder) ${name}`,
252	        description: path.join(ctx.workspaceRoot!, name),
253	      })),
254	    ];
255	
256	    const picked = await vscode.window.showQuickPick(items, {
257	      placeHolder: "Select a subdirectory or browse...",
258	      title: "Working Directory",
259	    });
260	
261	    if (!picked) {
262	      return { ok: false, workDir: null };
263	    }
264	
265	    let selected: string;
266	    if (picked.label === "$(folder) Browse...") {
267	      const result = await vscode.window.showOpenDialog({
268	        canSelectFiles: false,
269	        canSelectFolders: true,
270	        canSelectMany: false,
271	        defaultUri: workspaceUri,
272	        openLabel: "Select Working Directory",
273	      });
274	      if (!result || result.length === 0) {
275	        return { ok: false, workDir: null };
276	      }
277	      selected = result[0].fsPath;
278	    } else {
279	      selected = picked.description!;
280	    }
281	
282	    if (selected !== ctx.workspaceRoot && !selected.startsWith(ctx.workspaceRoot + path.sep)) {
283	      vscode.window.showWarningMessage("Selected directory must be within the workspace.");
284	      return { ok: false, workDir: null };
285	    }
286	
287	    ctx.setCustomWorkDir(selected === ctx.workspaceRoot ? null : selected);
288	    return { ok: true, workDir: selected };
289	  },
