291	  [Methods.LoadConsiliumSessionHistory]: async (params: LoadHistoryParams, ctx): Promise<StreamEvent[]> => {
292	    if (!UUID_REGEX.test(params.consiliumSessionId)) {
293	      return [];
294	    }
295	
296	    // Resolve the Think session file: check legacy global path first, then
297	    // workspace-local paths under each registered work dir.
298	    let thinkFile = path.join(getThinkDir(), `${params.consiliumSessionId}.jsonl`);
299	    let isThinkFile = fs.existsSync(thinkFile);
300	
301	    if (!isThinkFile) {
302	      // Search workspace-local paths
303	      const candidateDirs = new Set<string>();
304	      if (params.workDir) candidateDirs.add(params.workDir);
305	      if (ctx.workDir) candidateDirs.add(ctx.workDir);
306	      if (ctx.workspaceRoot) {
307	        for (const dir of getRegisteredWorkDirs(ctx.workspaceRoot)) {
308	          candidateDirs.add(dir);
309	        }
310	      }
311	      for (const dir of candidateDirs) {
312	        const wsFile = path.join(getWorkspaceThinkDir(dir), `${params.consiliumSessionId}.jsonl`);
313	        if (fs.existsSync(wsFile)) {
314	          thinkFile = wsFile;
315	          isThinkFile = true;
316	          break;
317	        }
318	      }
319	    }
320	
321	    // Think sessions can be loaded without a workspace; Do sessions require one.
322	    if (!isThinkFile && !ctx.workDir) {
323	      return [];
324	    }
325	
326	    const fileKey = ctx.getFileManagerKey();
327	    ctx.fileManager.setSessionId(fileKey, params.consiliumSessionId);
328	    if (ctx.workDir) {
329	      BaselineManager.initSession(ctx.workDir, params.consiliumSessionId);
330	    }
331	
332	    // ---- Think session path (base history) ----
333	    const thinkEvents: StreamEvent[] = [];
334	    if (isThinkFile) {
335	      const lines = (await fs.promises.readFile(thinkFile, "utf-8"))
336	        .split("\n")
337	        .filter((l) => l.trim());
338	      for (const line of lines) {
339	        try {
340	          const entry = JSON.parse(line);
341	          if (entry.role === "user" || entry.role === "assistant") {
342	            thinkEvents.push({
343	              type: "Message",
344	              payload: { role: entry.role, content: entry.content },
345	              _sessionId: params.consiliumSessionId,
346	              mode: 'think',
347	            } as any);
348	          }
349	        } catch {
350	          // ignore malformed lines
351	        }
352	      }
353	    }
354	
355	    const meta = ctx.getSessionMetadata(params.consiliumSessionId);
356	    // If a think file exists and the stored mode is not explicitly 'do', treat it as a Think session.
357	    // This protects against lost globalState after extension reinstall.
358	    const mode = meta?.mode || (isThinkFile ? 'think' : 'legacy');
359	    const resolvedMode: 'think' | 'do' = mode === 'do' ? 'do' : 'think';
360	
361	    if (resolvedMode === 'think') {
362	      // Force terminal event so Think tab doesn't get stuck
363	      thinkEvents.push({
364	        type: "history_restored",
365	        result: { status: "restored" },
366	        _sessionId: params.consiliumSessionId,
367	        mode: 'think',
368	      } as any);
369	      return thinkEvents;
370	    }
371	
372	    // ---- Regular Do session path ----
373	    // Prefer the workDir supplied by the caller; fall back to registered
374	    // variants to handle Windows case-sensitivity differences.
375	    let doEvents: StreamEvent[] = [];
376	    const candidateWorkDirs = new Set<string>();
377	    if (params.workDir) candidateWorkDirs.add(params.workDir);
378	    if (ctx.workDir) candidateWorkDirs.add(ctx.workDir);
379	    if (ctx.workspaceRoot) {
380	      for (const dir of getRegisteredWorkDirs(ctx.workspaceRoot)) {
381	        candidateWorkDirs.add(dir);
382	      }
383	    }
384	    if (candidateWorkDirs.size === 0) {
385	      return [];
386	    }
387	    for (const dir of candidateWorkDirs) {
388	      try {
389	        const events = await parseSessionEvents(dir, params.consiliumSessionId);
390	        if (events.length > 0) {
391	          doEvents = events;
392	          break;
393	        }
394	      } catch {
395	        // try next candidate
396	      }
397	    }
398	
399	    const events = [
400	      ...thinkEvents,
401	      ...doEvents.map((e) => ({ ...e, _sessionId: params.consiliumSessionId, mode: 'do' as const }) as any),
402	    ];
403	
404	    // If the previous CLI process was killed (window reload), wire.jsonl ends
405	    // mid-stream. The webview would stay stuck in isProcessing=true.
406	    // Append a history_restored event to unlock the UI.
407	    if (!ctx.getTurn()) {
408	      const last = events[events.length - 1] as any;
409	      const isTerminal =
410	        last &&
411	        (last.type === "stream_complete" ||
412	          last.type === "stream_aborted" ||
413	          last.type === "history_restored" ||
414	          last.type === "error" ||
415	          last.type === "turn_complete" ||
416	          last.type === "done");
417	      if (!isTerminal) {
418	        events.push({
419	          type: "history_restored",
420	          result: { status: "restored" },
421	          _sessionId: params.consiliumSessionId,
422	          mode: 'do',
423	        } as any);
424	      }
425	    }
426	
427	    return events;
428	  },
429	
430	  [Methods.DeleteConsiliumSession]: async (params: DeleteSessionParams, ctx): Promise<{ ok: boolean }> => {
431	    if (!ctx.workDir || !UUID_REGEX.test(params.sessionId)) {
432	      return { ok: false };
433	    }
434	    return { ok: await deleteSession(ctx.workDir, params.sessionId) };
435	  },
