459	      titleSource: source,
460	      titleGeneratedAt: source === "llm" ? Date.now() : meta.titleGeneratedAt,
461	    });
462	    ctx.broadcast(
463	      Events.SessionTitleUpdated,
464	      { sessionId, title, source },
465	      ctx.webviewId,
466	    );
467	    return { ok: true };
468	  },
469	
470	  [Methods.RestoreTabState]: async (_, ctx) => {
471	    return ctx.getRestoredTabState();
472	  },
473	};
