 3	import * as path from "node:path";
 4	import * as readline from "node:readline";
 5	import { ConsiliumPaths } from "../paths";
 6	import { log } from "../logger";
 7	import { parseEventPayload, type StreamEvent } from "../schema";
 8	
 9	export async function parseSessionEvents(workDir: string, sessionId: string): Promise<StreamEvent[]> {
10	  const sessionDir = ConsiliumPaths.sessionDir(workDir, sessionId);
11	  const wireFile = path.join(sessionDir, "wire.jsonl");
12	
13	  if (!fs.existsSync(wireFile)) {
14	    log.history("Wire file not found for session: %s", sessionId);
15	    return [];
16	  }
17	
18	  const stat = await fsp.stat(wireFile);
19	  if (stat.size === 0) {
20	    log.history("Wire file is empty for session: %s", sessionId);
21	    return [];
22	  }
23	
24	  log.history("Parsing wire file: %s (%d bytes)", wireFile, stat.size);
25	  return parseWireFile(wireFile);
26	}
27	
28	async function parseWireFile(filePath: string): Promise<StreamEvent[]> {
29	  const events: StreamEvent[] = [];
30	
31	  const stream = fs.createReadStream(filePath, { encoding: "utf-8" });
32	  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
33	
34	  for await (const line of rl) {
35	    if (!line.trim()) {
36	      continue;
37	    }
38	
39	    try {
40	      const record = JSON.parse(line);
41	      const event = parseWireRecord(record);
42	      if (event) {
43	        events.push(event);
44	      }
45	    } catch {
46	      // Skip invalid lines
47	    }
48	  }
49	
50	  log.history("Parsed %d events from wire file", events.length);
51	  return events;
52	}
53	
54	function parseWireRecord(record: unknown): StreamEvent | null {
55	  if (!record || typeof record !== "object") {
56	    return null;
57	  }
58	
59	  const rec = record as Record<string, unknown>;
60	  const message = rec.message as { type?: string; payload?: unknown } | undefined;
61	
62	  if (!message?.type) {
63	    return null;
64	  }
65	
66	  const result = parseEventPayload(message.type, message.payload);
67	  return result.ok ? result.value : null;
68	}

