18	/** Create a ConsiliumPaths object with custom shareDir */
19	export function createConsiliumPaths(shareDir?: string): ConsiliumPathsType {
20	  const home = shareDir || process.env.KIMI_SHARE_DIR || path.join(os.homedir(), ".consilium");
21	  return {
22	    home,
23	    config: path.join(home, "config.toml"),
24	    mcpConfig: path.join(home, "mcp.json"),
25	    sessionsDir(workDir: string): string {
26	      return path.join(home, "sessions", hashPath(workDir));
27	    },
28	    sessionDir(workDir: string, sessionId: string): string {
29	      return path.join(home, "sessions", hashPath(workDir), sessionId);
30	    },
31	    baselineDir(workDir: string, sessionId: string): string {
32	      return path.join(home, "sessions", hashPath(workDir), sessionId, "baseline");
33	    },
34	  };
35	}
