  9	
 10	// ============================================================================
 11	// consilium.json & metadata.json helpers
 12	// ============================================================================
 13	
 14	function readConsiliumJson(): { work_dirs?: Array<{ path: string }> } | null {
 15	  try {
 16	    return JSON.parse(fs.readFileSync(path.join(ConsiliumPaths.home, "consilium.json"), "utf-8"));
 17	  } catch {
 18	    return null;
 19	  }
 20	}
