 30	// Constants
 31	const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 32	
 33	// Fork Session Types
 34	export interface ForkSessionOptions {
 35	  workDir: string;
 36	  sourceSessionId: string;
 37	  /** 0-indexed turn number to fork after (0 = after first turn) */
 38	  turnIndex: number;
 39	}
 40	
 41	export interface ForkSessionResult {
 42	  sessionId: string;
 43	  sessionDir: string;
 44	}
