 88	/** List Think-mode sessions from ~/.consilium/think_sessions */
 89	export async function listThinkSessions(workspaceRoot: string): Promise<SessionInfo[]> {
 90	  const thinkDir = path.join(ConsiliumPaths.home, "think_sessions");
 91	
 92	  try {
 93	    await fsp.access(thinkDir);
 94	  } catch {
 95	    return [];
 96	  }
 97	
 98	  let entries: fs.Dirent[];
 99	  try {
100	    entries = await fsp.readdir(thinkDir, { withFileTypes: true });
101	  } catch (err) {
102	    console.warn("[storage] Failed to read think sessions:", err);
103	    return [];
104	  }
105	
106	  const sessions: SessionInfo[] = [];
107	
108	  for (const entry of entries) {
109	    if (!entry.isFile() || !entry.name.endsWith(".jsonl")) {
110	      continue;
111	    }
112	
113	    const sessionId = entry.name.replace(".jsonl", "");
114	    if (!UUID_REGEX.test(sessionId)) {
115	      continue;
116	    }
117	
118	    const filePath = path.join(thinkDir, entry.name);
119	
120	    try {
121	      const stat = await fsp.stat(filePath);
122	      if (stat.size === 0) {
123	        continue;
124	      }
125	
126	      const brief = await getFirstUserMessageFromThinkFile(filePath);
127	      if (!brief) {
128	        continue;
129	      }
130	
131	      sessions.push({
132	        id: sessionId,
133	        workDir: workspaceRoot,
134	        contextFile: filePath,
135	        updatedAt: stat.mtimeMs,
136	        brief: `[Think] ${brief}`,
137	        isThinking: true,
138	      });
139	    } catch (err) {
140	      log.storage("Failed to stat think session %s: %O", sessionId, err);
141	    }
142	  }
143	
144	  return sessions.sort((a, b) => b.updatedAt - a.updatedAt);
145	}
