209	// Delete Session
210	export async function deleteSession(workDir: string, sessionId: string): Promise<boolean> {
211	  const sessionDir = path.join(ConsiliumPaths.sessionsDir(workDir), sessionId);
212	
213	  try {
214	    await fsp.access(sessionDir);
215	  } catch {
216	    return false;
217	  }
218	
219	  try {
220	    await fsp.rm(sessionDir, { recursive: true, force: true });
221	    log.storage("Deleted session %s", sessionId);
222	    return true;
223	  } catch (err) {
224	    log.storage("Failed to delete session %s: %O", sessionId, err);
225	    return false;
226	  }
227	}
