497	/**
498	 * Remove assistant messages with incomplete tool_calls (missing tool responses).
499	 */
500	function removeIncompleteToolCalls(lines: string[]): string[] {
501	  // Collect tool_call IDs from assistant messages and tool responses
502	  const expectedIds = new Set<string>();
503	  const receivedIds = new Set<string>();
504	  const assistantIndicesWithToolCalls: number[] = [];
505	
506	  for (let i = 0; i < lines.length; i++) {
507	    try {
508	      const record = JSON.parse(lines[i]);
509	      if (record.role === "assistant" && Array.isArray(record.tool_calls)) {
510	        for (const tc of record.tool_calls) {
511	          if (tc.id) expectedIds.add(tc.id);
512	        }
513	        if (record.tool_calls.length > 0) {
514	          assistantIndicesWithToolCalls.push(i);
515	        }
516	      } else if (record.role === "tool" && record.tool_call_id) {
517	        receivedIds.add(record.tool_call_id);
518	      }
519	    } catch {
520	      continue;
521	    }
522	  }
523	
524	  // Check if all tool_calls have responses
525	  const hasIncomplete = [...expectedIds].some((id) => !receivedIds.has(id));
526	  if (!hasIncomplete) {
527	    return lines;
528	  }
529	
530	  // Find the last assistant with incomplete tool_calls and truncate before it
531	  for (let i = assistantIndicesWithToolCalls.length - 1; i >= 0; i--) {
532	    const idx = assistantIndicesWithToolCalls[i];
533	    try {
534	      const record = JSON.parse(lines[idx]);
535	      const ids = (record.tool_calls || []).map((tc: { id?: string }) => tc.id).filter(Boolean);
536	      const incomplete = ids.some((id: string) => !receivedIds.has(id));
537	      if (incomplete) {
538	        log.storage("Removing incomplete assistant message at index %d", idx);
539	        // Keep lines before this assistant, plus any markers after
540	        const before = lines.slice(0, idx);
541	        const after = lines.slice(idx + 1).filter((l) => {
542	          try {
543	            const r = JSON.parse(l);
544	            return r.role === "_checkpoint" || r.role === "_usage";
545	          } catch {
546	            return false;
547	          }
548	        });
549	        return [...before, ...after];
550	      }
551	    } catch {
552	      continue;
553	    }
554	  }
555	
556	  return lines;
557	}

