 1	import { useState, useEffect, useCallback } from "react";
 2	import { bridge } from "@/services";
 3	
 4	interface UseInputHistoryOptions {
 5	  text: string;
 6	  setText: (text: string) => void;
 7	  onHeightChange?: () => void;
 8	}
 9	
10	export function useInputHistory({ text, setText, onHeightChange }: UseInputHistoryOptions) {
11	  const [history, setHistory] = useState<string[]>([]);
12	  const [index, setIndex] = useState(-1);
13	
14	  useEffect(() => {
15	    bridge.getInputHistory().then(setHistory);
16	  }, []);
17	
18	  const add = useCallback((input: string) => {
19	    const trimmed = input.trim();
20	    if (!trimmed) {
21	      return;
22	    }
23	
24	    bridge.addInputHistory(trimmed);
25	    setHistory((prev) => (prev[prev.length - 1] === trimmed ? prev : [...prev, trimmed]));
26	    setIndex(-1);
27	  }, []);
28	
29	  const handleKey = useCallback(
30	    (e: React.KeyboardEvent): boolean => {
31	      // Ignore if any modifier key is pressed
32	      if (e.ctrlKey || e.metaKey || e.altKey) {
33	        return false;
34	      }
35	
36	      if (e.key === "ArrowUp" && history.length > 0 && (!text || index >= 0)) {
37	        const newIndex = Math.min(index + 1, history.length - 1);
38	        if (newIndex !== index) {
39	          e.preventDefault();
40	          setIndex(newIndex);
41	          setText(history[history.length - 1 - newIndex]);
42	          onHeightChange?.();
43	          return true;
44	        }
45	      }
46	
47	      if (e.key === "ArrowDown" && index >= 0) {
48	        e.preventDefault();
49	        const newIndex = index - 1;
50	        setIndex(newIndex);
51	        setText(newIndex === -1 ? "" : history[history.length - 1 - newIndex]);
52	        onHeightChange?.();
53	        return true;
54	      }
55	
56	      return false;
57	    },
58	    [history, index, text, setText, onHeightChange],
59	  );
60	
61	  const reset = useCallback(() => setIndex(-1), []);
62	
63	  return { handleKey, add, reset };
64	}

