114	export default function App() {
115	  const { status, errorMessage, cliResult, modelsCount, refresh } = useAppInit();
116	  const extensionConfig = useSettingsStore((s) => s.extensionConfig);
117	  const [forceShowSetup, setForceShowSetup] = useState(false);
118	
119	  const handleSetupSuccess = useCallback(() => {
120	    setForceShowSetup(false);
121	    refresh();
122	  }, [refresh]);
123	
124	  // Show setup screen if no API key is configured or if explicitly requested
125	  const hasApiKey = !!extensionConfig?.apiKey;
126	  const shouldShowSetup = !hasApiKey || forceShowSetup;
127	
128	  if (shouldShowSetup && status !== "loading" && status !== "cli-error" && status !== "no-workspace") {
129	    return (
130	      <div className="flex flex-col h-screen text-foreground overflow-hidden">
131	        <Header />
132	        <SetupScreen onSetupSuccess={handleSetupSuccess} />
133	        <Toaster position="top-center" />
134	      </div>
135	    );
136	  }
137	
138	  // 如果没有模型
139	  if (modelsCount === 0 && status === "no-models") {
140	    return (
141	      <div className="flex flex-col h-screen text-foreground overflow-hidden">
142	        <Header />
143	        <ConfigErrorScreen type="no-models" cliResult={cliResult} errorMessage={errorMessage} onRefresh={refresh} onOpenSetup={() => setForceShowSetup(true)} />
144	        <Toaster position="top-center" />
145	      </div>
146	    );
147	  }
148	
149	  // 其他错误状态
150	  if (status === "cli-error" || status === "no-workspace") {
151	    return (
152	      <div className="flex flex-col h-screen text-foreground overflow-hidden">
153	        <Header />
154	        <ConfigErrorScreen type={status} cliResult={cliResult} errorMessage={errorMessage} />
155	        <Toaster position="top-center" />
156	      </div>
157	    );
158	  }
159	
160	  // 正常状态
161	  return (
162	    <div className="flex flex-col h-screen text-foreground overflow-hidden">
163	      <Header />
164	      <MainContent onAuthAction={() => setForceShowSetup(true)} />
165	      <Toaster position="top-center" />
166	    </div>
167	  );
168	}

  1	import { useState, useEffect, useCallback } from "react";
  2	import { bridge, Events } from "@/services";
  3	import { useSettingsStore } from "@/stores";
  4	import type { ExtensionConfig, CLICheckResult } from "shared/types";
  5	
  6	export type AppStatus = "loading" | "no-workspace" | "cli-error" | "not-logged-in" | "no-models" | "ready";
  7	
  8	export interface AppInitState {
  9	  status: AppStatus;
 10	  errorMessage: string | null;
 11	  cliResult: CLICheckResult | null;
 12	  modelsCount: number;
 13	  refresh: () => void;
 14	}
 15	
 16	export function useAppInit(): AppInitState {
 17	  const [state, setState] = useState<Omit<AppInitState, "refresh">>({
 18	    status: "loading",
 19	    errorMessage: null,
 20	    cliResult: null,
 21	    modelsCount: 0,
 22	  });
 23	  const [initKey, setInitKey] = useState(0);
 24	  const { initModels, setExtensionConfig, setMCPServers, setWireSlashCommands, setIsLoggedIn, setWorkspaceRoot } = useSettingsStore();
 25	
 26	  const refresh = useCallback(() => {
 27	    setState({ status: "loading", errorMessage: null, cliResult: null, modelsCount: 0 });
 28	    setInitKey((k) => k + 1);
 29	  }, []);
 30	
 31	  useEffect(() => {
 32	    return bridge.on<{ config: ExtensionConfig; changedKeys: string[] }>(Events.ExtensionConfigChanged, ({ config, changedKeys }) => {
 33	      setExtensionConfig(config);
 34	      if (changedKeys.includes("executablePath")) {
 35	        refresh();
 36	      }
 37	    });
 38	  }, [setExtensionConfig, refresh]);
 39	
 40	  useEffect(() => {
 41	    let cancelled = false;
 42	
 43	    async function init() {
 44	      try {
 45	        const workspace = await bridge.checkWorkspace();
 46	        if (cancelled) {
 47	          return;
 48	        }
 49	
 50	        if (!workspace.hasWorkspace) {
 51	          setState({ status: "no-workspace", errorMessage: null, cliResult: null, modelsCount: 0 });
 52	          return;
 53	        }
 54	
 55	        setWorkspaceRoot(workspace.workspaceRoot ?? workspace.path ?? null);
 56	
 57	        const [extensionConfig, mcpServers, cliResult] = await Promise.all([bridge.getExtensionConfig(), bridge.getMCPServers(), bridge.checkCLI()]);
 58	        if (cancelled) {
 59	          return;
 60	        }
 61	
 62	        setExtensionConfig(extensionConfig);
 63	        setMCPServers(mcpServers);
 64	        setWireSlashCommands(cliResult.slashCommands ?? []);
 65	
 66	        if (!cliResult.ok) {
 67	          setState({
 68	            status: "cli-error",
 69	            errorMessage: cliResult.error?.message ?? "CLI check failed",
 70	            cliResult,
 71	            modelsCount: 0,
 72	          });
 73	          return;
 74	        }
 75	
 76	        const [loginStatus, consiliumConfig] = await Promise.all([bridge.checkLoginStatus(), bridge.getModels()]);
 77	        if (cancelled) {
 78	          return;
 79	        }
 80	
 81	        console.log("[AppInit] Login status:", loginStatus, "consiliumConfig:", consiliumConfig);
 82	
 83	        setIsLoggedIn(loginStatus.loggedIn);
 84	        let finalModels = consiliumConfig.models || [];
 85	        if (extensionConfig.apiKey) {
 86	          const defaultThink = extensionConfig.defaultThinkModel?.trim();
 87	          const defaultDo = extensionConfig.defaultDoModel?.trim();
 88	          const customModels = [];
 89	          if (defaultThink && !finalModels.find(m => m.id === defaultThink)) {
 90	            customModels.push({ id: defaultThink, name: defaultThink, capabilities: ["thinking"] as any[] });
 91	          }
 92	          if (defaultDo && defaultDo !== defaultThink && !finalModels.find(m => m.id === defaultDo)) {
 93	            customModels.push({ id: defaultDo, name: defaultDo, capabilities: [] });
 94	          }
 95	          finalModels = [...finalModels, ...customModels];
 96	          consiliumConfig.models = finalModels;
 97	        }
 98	
 99	        initModels(finalModels, consiliumConfig.defaultModel, consiliumConfig.defaultThinking);
100	
101	        const modelsCount = finalModels.length;
102	
103	        if (!loginStatus.loggedIn && !extensionConfig.apiKey) {
104	          setState({ status: "not-logged-in", errorMessage: null, cliResult, modelsCount });
105	          return;
106	        }
107	
108	        if (modelsCount === 0 && !extensionConfig.apiKey) {
109	          setState({ status: "no-models", errorMessage: null, cliResult, modelsCount: 0 });
110	          return;
111	        }
112	
113	        setState({ status: "ready", errorMessage: null, cliResult, modelsCount });
114	      } catch (err) {
115	        if (!cancelled) {
116	          setState({
117	            status: "cli-error",
118	            errorMessage: err instanceof Error ? err.message : "Failed to initialize",
119	            cliResult: null,
120	            modelsCount: 0,
121	          });
122	        }
123	      }
124	    }
125	
126	    init();
127	    return () => {
128	      cancelled = true;
129	    };
130	  }, [initKey, initModels, setExtensionConfig, setMCPServers, setWireSlashCommands, setIsLoggedIn]);
131	
132	  return { ...state, refresh };
133	}

