 86	  on<T>(event: string, handler: (data: T) => void): () => void {
 87	    if (!this.eventHandlers.has(event)) {
 88	      this.eventHandlers.set(event, new Set());
 89	    }
 90	    this.eventHandlers.get(event)!.add(handler as (data: unknown) => void);
 91	
 92	    return () => {
 93	      this.eventHandlers.get(event)?.delete(handler as (data: unknown) => void);
 94	    };
 95	  }
