 29	export function getModelThinkingMode(model: ModelConfig): ThinkingMode {
 30	  if (model.name.toLowerCase().includes("think")) {
 31	    return "always";
 32	  }
 33	  if (model.capabilities.includes("always_thinking")) {
 34	    return "always";
 35	  }
 36	  if (model.capabilities.includes("thinking")) {
 37	    return "switch";
 38	  }
 39	  return "none";
 40	}
