107	export const useSettingsStore = create<SettingsState>((set, get) => ({
108	  currentModel: "",
109	  thinkingEnabled: false,
110	  extensionConfig: DEFAULT_EXTENSION_CONFIG,
111	  mcpServers: [],
112	  mcpModalOpen: false,
113	  workDirModalOpen: false,
114	  currentWorkDir: null,
115	  workspaceRoot: null,
116	  models: [],
117	  defaultModel: null,
118	  defaultThinking: false,
119	  modelsLoaded: false,
120	  wireSlashCommands: [],
121	  slashCommands: [],
122	  isLoggedIn: false,
123	  generationConfigOpen: false,
124	
125	  setCurrentModel: (currentModel) => set({ currentModel }),
126	
127	  setThinkingEnabled: (thinkingEnabled) => set({ thinkingEnabled }),
128	
129	  updateModel: (modelId) => {
130	    const { models, defaultThinking } = get();
131	    const model = getModelById(models, modelId);
132	    if (!model) {
133	      return;
134	    }
135	
136	    const thinkingMode = getModelThinkingMode(model);
137	    let thinkingEnabled: boolean;
138	
139	    if (thinkingMode === "always") {
140	      thinkingEnabled = true;
141	    } else if (thinkingMode === "none") {
142	      thinkingEnabled = false;
143	    } else {
144	      // switch mode - use default preference
145	      thinkingEnabled = defaultThinking;
146	    }
147	
148	    set({ currentModel: modelId, thinkingEnabled });
149	    bridge.saveConfig({ model: modelId, thinking: thinkingEnabled });
150	  },
151	
152	  toggleThinking: () => {
153	    const { models, currentModel, thinkingEnabled } = get();
154	    const model = getModelById(models, currentModel);
155	    if (!model) {
156	      return;
157	    }
158	
159	    const thinkingMode = getModelThinkingMode(model);
160	    if (thinkingMode !== "switch") {
161	      return;
162	    } // Can only toggle in switch mode
163	
164	    const newThinking = !thinkingEnabled;
165	    set({ thinkingEnabled: newThinking, defaultThinking: newThinking });
166	    bridge.saveConfig({ model: currentModel, thinking: newThinking });
167	  },
168	
169	  setExtensionConfig: (extensionConfig) => set({ extensionConfig }),
170	
171	  setGenerationConfigOpen: (generationConfigOpen) => set({ generationConfigOpen }),
172	
173	  updateGenerationConfig: (partial) => {
174	    const { extensionConfig } = get();
175	    const newConfig = { ...extensionConfig.generationConfig, ...partial };
176	    set({
177	      extensionConfig: { ...extensionConfig, generationConfig: newConfig },
178	    });
179	    bridge.saveConfig({
180	      model: get().currentModel,
181	      thinking: get().thinkingEnabled,
182	      generation: newConfig,
183	    });
184	  },
185	
186	  setMCPServers: (mcpServers) => set({ mcpServers }),
187	
188	  setMCPModalOpen: (mcpModalOpen) => set({ mcpModalOpen }),
189	
190	  setWorkDirModalOpen: (workDirModalOpen) => set({ workDirModalOpen }),
191	
192	  setCurrentWorkDir: (currentWorkDir) => set({ currentWorkDir }),
193	
194	  setWorkspaceRoot: (workspaceRoot) => set({ workspaceRoot }),
195	
196	  initModels: (models, defaultModel, defaultThinking) => {
197	    const initialModel = defaultModel || (models.length > 0 ? models[0].id : "");
198	    const model = getModelById(models, initialModel);
199	
200	    let thinkingEnabled = false;
201	    if (model) {
202	      const thinkingMode = getModelThinkingMode(model);
203	      if (thinkingMode === "always") {
204	        thinkingEnabled = true;
205	      } else if (thinkingMode === "switch") {
206	        thinkingEnabled = defaultThinking;
207	      }
208	    }
209	
210	    set({
211	      models,
212	      defaultModel,
213	      defaultThinking,
214	      modelsLoaded: true,
215	      currentModel: initialModel,
216	      thinkingEnabled,
217	    });
218	  },
219	
220	  setWireSlashCommands: (commands) => {
221	    set({
222	      wireSlashCommands: commands,
223	      slashCommands: commands,
224	    });
225	  },
226	
227	  setIsLoggedIn: (isLoggedIn) => set({ isLoggedIn }),
228	
229	  getCurrentThinkingMode: () => {
230	    const { models, currentModel } = get();
231	    const model = getModelById(models, currentModel);
232	    if (!model) {
233	      return "none";
234	    }
235	    return getModelThinkingMode(model);
236	  },
237	}));

