import { IconLoader2, IconFolderOpen } from "@tabler/icons-react";
import { Button } from "@/components/ui/button";
import { ConsiliumLogo } from "./ConsiliumLogo";
import { bridge } from "@/services";
import { useSettingsStore } from "@/stores";
import { toast } from "@/components/ui/sonner";

interface Props {
  onSetupComplete: () => void;
}

export function ProjectSetupScreen({ onSetupComplete }: Props) {
  const [initializing, setInitializing] = useState(false);

  const handleInitialize = async () => {
    setInitializing(true);
    try {
      const result = await bridge.initializeProject();
      if (result.success) {
        toast.success("Project initialized");
        onSetupComplete();
      } else {
        toast.error(result.error || "Failed to initialize project");
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to initialize project");
    } finally {
      setInitializing(false);
    }
  };

  const handleSkip = () => {
    useSettingsStore.setState({ projectSetupSkipped: true });
    onSetupComplete();
  };

  return (
    <div className="h-full flex items-center justify-center p-6">
      <div className="max-w-sm text-center space-y-6">
        <ConsiliumLogo className="h-40 mx-auto opacity-50" />
        <div className="space-y-2">
          <div className="inline-flex items-center gap-2 text-amber-500">
            <IconFolderOpen className="size-5" />
            <span className="text-sm font-medium">Project Setup</span>
          </div>
          <p className="text-xs text-muted-foreground/70">
            This workspace hasn't been initialized for Consilium yet.
            Set up the project structure for sessions and agents to get started.
          </p>
        </div>
        <div className="flex flex-col gap-2">
          <Button onClick={handleInitialize} disabled={initializing} className="gap-2">
            {initializing ? (
              <>
                <IconLoader2 className="size-4 animate-spin" />
                Initializing...
              </>
            ) : (
              <>
                <IconFolderOpen className="size-4" />
                Initialize Project
              </>
            )}
          </Button>
          <Button onClick={handleSkip} variant="ghost" size="sm" className="text-muted-foreground">
            Skip
          </Button>
        </div>
      </div>
    </div>
  );
}"}

